// RenderAppBody implements ownframe.Config.Render without html/template reflection.
func RenderAppBody(w io.Writer, data any) error {
	var src *View
	switch d := data.(type) {
	case *View:
		src = d
	case View:
		src = &d
	}
	if src == nil {
		return nil
	}
	if buf, ok := w.(*bytes.Buffer); ok {
		RenderAppBodyBuf(buf, src)
		return nil
	}
	var buf bytes.Buffer
	RenderAppBodyBuf(&buf, src)
	_, err := w.Write(buf.Bytes())
	return err
}

